import org.junit.Test;
import static org.junit.Assert.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URI;
import java.io.UnsupportedEncodingException;
import java.util.HashMap;

public class UrlBuilderTest {

    @Test
    public void build_WithoutQueryOrFragment_ReturnsOriginalUrl() throws MalformedURLException {
        URL inputUrl = new URL("http://example.com/path?query#fragment");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(inputUrl, urlBuilder.build());
    }

    @Test
    public void build_WithQuery_ReturnsNormalizedUrl() throws MalformedURLException {
        URL inputUrl = new URL("http://example.com/path?query=Hello%2C+World");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(new URL("http://example.com/path?query=Hello%2C%20World"), urlBuilder.build());
    }

    @Test
    public void build_WithQueryAndFragment_ReturnsNormalizedUrl() throws MalformedURLException {
        URL inputUrl = new URL("http://example.com/path?query=Hello%2C+World#fragment");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(new URL("http://example.com/path?query=Hello%2C%20World#fragment"), urlBuilder.build());
    }

    @Test
    public void appendKeyVal_AppendsKeyValuePair() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com/path"));
        urlBuilder.appendKeyVal(kv);
        assertEquals("http://example.com/path?key=value", new URL("http://example.com/path").toString());
    }

    @Test
    public void decodePart_DecodesASCIIStrings() throws UnsupportedEncodingException {
        String encoded = "Hello%2C+World";
        String decoded = UrlBuilder.decodePart(encoded);
        assertEquals("Hello, World", decoded);
    }

    @Test
    public void normalizeQuery_ReplacesSpacesWithPlusSigns() {
        String q = "Hello World";
        String normalizedQ = UrlBuilder.normalizeQuery(q);
        assertEquals("Hello+World", normalizedQ);
    }

    @Test
    public void normalizeRef-ReplacesSpacesWithPercent20Symbols() {
        String r = "Hello World";
        String normalizedR = UrlBuilder.normalizeRef(r);
        assertEquals("Hello%20World", normalizedR);
    }
}
