    public void testConnectionKeyValCreation() {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        assertEquals("key", kv.getKey());
        assertEquals("value", kv.getValue());
    }

    @Test
    public void testUrlBuilderAppendKeyVal() {
        URL url = new URL("http://example.com");
        UrlBuilder builder = new UrlBuilder(url);
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        builder.appendKeyVal(kv);
        assertEquals("key=value", builder.getUrlQuery());
    }

    @Test
    public void testUrlBuilderDecodePart() {
        String encoded = "%20Hello World";
        assertEquals("Hello World", UrlBuilder.decodePart(encoded));
    }

    @Test
    public void testUrlBuilderNormalizeQuery() {
        String query = "key=value&another=parameter";
        assertEquals("key=value&another%3Dparameter", UrlBuilder.normalizeQuery(query));
    }

    @Test
    public void testUrlBuilderNormalizeRef() {
        String ref = "Hello World!";
        assertEquals("%20Hello%20World!", UrlBuilder.normalizeRef(ref));
    }
